function loadBatchText(txt, name) { batchItems = txt.split("\n").map(s => s.trim()).filter(Boolean).map(s => JSON.parse(s)); batchName = name; const fams = [...new Set(batchItems.map(i => i.family))]; $("#b-info").textContent = `${name}: ${batchItems.length} state / family: ${fams.join(", ")}`; $("#b-run").disabled = !jev; $("#i-run").disabled = !jev; }
$("#b-file").onchange = async e => { const f = e.target.files[0]; if (f) loadBatchText(await f.text(), f.name); };
$("#b-sample").onclick = async () => { const f = $("#b-ds").value; loadBatchText(await (await fetch("bench/" + f)).text(), f); };
(async () => { try { const idx = await (await fetch("bench/index.json")).json(); for (const f of idx.files) { const o = document.createElement("option"); o.value = f.file; o.textContent = `${f.file} — ${f.desc || ""} (${f.states})`; $("#b-ds").appendChild(o); } } catch { } })();
const selectedBatch = (famSel = "#b-family", limSel = "#b-limit") => { const fam = $(famSel).value.split(",").map(s => s.trim()).filter(Boolean); const lim = +$(limSel).value || 0; let it = fam.length ? batchItems.filter(i => fam.some(f => i.family === f || i.family.startsWith(f))) : batchItems; return lim ? it.slice(0, lim) : it; };
const goldOf = (q, g) => q.type === "noul" ? (["yes", "true", "1"].includes(String(g).toLowerCase()) ? "yes" : "no") : String(g);
$("#b-stop").onclick = () => { batchStop = true; };
$("#b-run").onclick = async () => { if (!ready()) return; const items = selectedBatch(); if (!items.length) return alert("該当データがありません"); const rows = [], lat = [], perRow = []; const useCtx = $("#b-ctx").checked; batchStop = false; $("#b-stop").disabled = false; let i = 0;
  for (const it of items) { if (batchStop) break; status(`評価中 ${++i}/${items.length}`); $("#b-prog").style.width = (100 * i / items.length).toFixed(0) + "%"; const r = await jev.decide(it.state, it.questions, useCtx ? it.context : null, curOpts()); lat.push(r.latency_ms);
    it.questions.forEach((q, k) => { const a = r.answers[k]; const gold = goldOf(q, it.gold[q.id]); const labels = a.distribution.labels, p = a.distribution.probabilities, gi = labels.indexOf(gold), pi = p.indexOf(Math.max(...p)); const row = { family: it.family || "?", type: q.type, correct: pi === gi, conf: p[pi], brier: p.reduce((s, x, j) => s + (x - (j === gi ? 1 : 0)) ** 2, 0) }; if (q.type === "score") { const vals = q.values || labels.map((_, j) => j); row.mae = Math.abs(p.reduce((s, x, j) => s + x * vals[j], 0) - vals[gi]); } rows.push(row); perRow.push({ id: it.id, family: it.family, q: q.id, type: q.type, gold, pred: labels[pi], conf: p[pi], correct: row.correct, ms: r.latency_ms }); }); }
  $("#b-stop").disabled = true; const m = metrics(rows, lat); const o = curOpts(); batchResult = { data: batchName + ($("#b-family").value ? " [" + $("#b-family").value + "]" : ""), device: navigator.userAgent, results: [{ model: jev.name + " (" + optsLabel(o) + ", device)", probability_kind: "native", use_context: useCtx, backend: jev.backend, opts: o, ...m }], rows: perRow };
  await saveNote({ kind: "batch", name: $("#b-name").value || `${jev.name} ${optsLabel(o)} ${batchName}`, model: jev.name, head: jev.headCustom ? "custom" : "export", method: o.method, pool: o.pool, T: o.T, cosScale: o.cosScale, dataset: batchResult.data, n_states: i, use_context: useCtx, backend: jev.backend, accuracy: m.accuracy, brier: m.brier, ece: m.ece, latency_p50_ms: m.latency_p50_ms, latency_p95_ms: m.latency_p95_ms, n_questions: m.n_questions, per_family: m.per_family, ece_table: m.ece_table, rows: perRow });
  $("#b-out").innerHTML = `<div><span class="stat">精度<br><b>${(m.accuracy * 100).toFixed(1)}%</b></span><span class="stat">Brier<br><b>${m.brier.toFixed(3)}</b></span><span class="stat">ECE<br><b>${m.ece.toFixed(3)}</b></span><span class="stat">p50<br><b>${fmt(m.latency_p50_ms, 0)}</b> ms</span><span class="stat">n<br><b>${m.n_questions}</b></span></div><h2>family 別</h2><table><tr><th>family</th><th>n</th><th>精度</th><th>MAE</th></tr>${Object.entries(m.per_family).map(([k, v]) => `<tr><td>${esc(k)}</td><td>${v.n}</td><td>${(v.accuracy * 100).toFixed(1)}%</td><td>${v.mae != null ? v.mae.toFixed(2) : ""}</td></tr>`).join("")}</table><h2>較正</h2><table><tr><th>bin</th><th>n</th><th>conf</th><th>acc</th></tr>${m.ece_table.filter(b => b.n).map(b => `<tr><td>${b.bin}</td><td>${b.n}</td><td>${b.confidence.toFixed(2)}</td><td>${b.accuracy.toFixed(2)}</td></tr>`).join("")}</table><details><summary>行ごと（${perRow.length}）</summary><table><tr><th>id</th><th>q</th><th>gold</th><th>pred</th><th>conf</th><th>✓</th></tr>${perRow.map(r => `<tr><td>${esc(r.id)}</td><td>${esc(r.q)}</td><td>${esc(r.gold)}</td><td>${esc(r.pred)}</td><td>${r.conf.toFixed(2)}</td><td>${r.correct ? "✓" : ""}</td></tr>`).join("")}</table></details>`;
  drawCal(m.ece_table); status(""); $("#b-prog").style.width = "0"; };
function drawCal(bins) { const c = $("#b-cal"); c.classList.remove("hidden"); const g = c.getContext("2d"); const W = c.width, H = c.height, P = 36; g.clearRect(0, 0, W, H); g.strokeStyle = "#6b7280"; g.fillStyle = "#6b7280"; g.font = "12px system-ui"; g.beginPath(); g.moveTo(P, H - P); g.lineTo(W - P, H - P); g.lineTo(W - P, P); g.stroke(); g.setLineDash([4, 4]); g.beginPath(); g.moveTo(P, H - P); g.lineTo(W - P, P); g.stroke(); g.setLineDash([]); g.fillText("確信度 →", P, H - 10); const tot = bins.reduce((s, b) => s + b.n, 0); for (const b of bins) if (b.n) { g.fillStyle = "#0b6e99aa"; g.beginPath(); g.arc(P + b.confidence * (W - 2 * P), H - P - b.accuracy * (H - 2 * P), 4 + 14 * Math.sqrt(b.n / tot), 0, 7); g.fill(); } }
$("#b-dl").onclick = () => { if (batchResult) download(`bench-device-${Date.now()}.json`, JSON.stringify(batchResult, null, 1)); };
$("#b-csv").onclick = () => { if (!batchResult) return; const rows = batchResult.rows; download("bench-rows.csv", "﻿" + [Object.keys(rows[0]).join(",")].concat(rows.map(r => Object.values(r).map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))).join("\n"), "text/csv"); };

