let trainedHead = null;
function refreshImprove() { $("#i-state").innerHTML = jev?.kind === "jev_ja" ? `ヘッド: <b>${jev.headCustom ? "端末で学習したもの（" + (jev.headCustom.trained_on || "") + "）" : "書き出し時のもの"}</b> ・ d=${jev.cfg.hidden}, hidden=${jev.cfg.head?.hidden || 512}` : "JEV-JA を読み込むと使えます"; $("#i-run").disabled = !(jev?.kind === "jev_ja"); }
$("#i-src").onchange = () => $("#i-file").classList.toggle("hidden", $("#i-src").value !== "file");
async function improveItems() { const src = $("#i-src").value; if (src === "batch") return selectedBatch("#i-family", "#i-limit"); if (src === "file") { const f = $("#i-file").files[0]; if (!f) throw new Error("JSONL を選んでください"); return (await f.text()).split("\n").filter(s => s.trim()).map(s => JSON.parse(s)).slice(0, +$("#i-limit").value || 1e9); }
  const q = $("#o-q").value; const out = []; oItems.forEach((it, i) => { const L = oLabels[i]; if (it.error || !L) return; const qs = [], gold = {}; if (L.kind) { qs.push(OSINT_QUESTIONS(q)[1]); gold.kind = L.kind; } if (L.trust) { qs.push({ type: "score", id: "trust", instructions: "この情報の信頼性", levels: ["低", "中", "高"] }); gold.trust = L.trust; } if (qs.length) out.push({ id: "osint-" + i, family: "osint_ja", state: `${it.title}\n${it.text}`, context: oGeo.slice(0, 3), questions: qs, gold }); }); return out; }
$("#i-run").onclick = async () => { if (!ready() || jev.kind !== "jev_ja") return; let items; try { items = await improveItems(); } catch (e) { return alert(e.message); } if (items.length < 4) return alert("学習データが少なすぎます（4 件以上）");
  const valR = Math.min(0.5, Math.max(0, +$("#i-val").value || 0.2)); items = items.sort(() => Math.random() - 0.5); const nv = Math.floor(items.length * valR); const val = items.slice(0, nv), tr = items.slice(nv); const ex = { tr: [], val: [] }; let i = 0;
  for (const [set, arr] of [["tr", tr], ["val", val]]) for (const it of arr) { status(`ベクトル化 ${++i}/${items.length}`); const r = await jev.analyze(it.state, it.questions, it.context); r.questions.forEach(qr => { const y = qr.labels.indexOf(goldOf(qr.q, it.gold[qr.q.id])); if (y >= 0) ex[set].push({ u: qr.u, V: qr.Vs, y }); }); }
  const evalHead = h => { const sets = { tr: ex.tr, val: ex.val }; const out = {}; for (const k in sets) { let c = 0, b = 0; for (const e of sets[k]) { const p = softmax(h.logits(e.u, e.V), 1); if (p.indexOf(Math.max(...p)) === e.y) c++; b += p.reduce((s, x, j) => s + (x - (j === e.y ? 1 : 0)) ** 2, 0); } out[k] = sets[k].length ? { acc: c / sets[k].length, brier: b / sets[k].length, n: sets[k].length } : null; } return out; };
  const base = jev.headCustom || jev.headExport; const before = evalHead(base); const h = base.clone(); const curve = []; const ep = +$("#i-ep").value || 8, lr = +$("#i-lr").value || 1e-3, lam = +$("#i-lam").value;
  await new Promise(r => setTimeout(r, 30)); const t0 = performance.now();
  h.train(ex.tr, { epochs: ep, lr, lam, onEpoch: (e, loss, acc) => { curve.push({ e, loss, acc }); status(`学習中 epoch ${e + 1}/${ep} loss=${loss.toFixed(3)} acc=${(acc * 100).toFixed(0)}%`); } });
  const after = evalHead(h); trainedHead = h; trainedHead.trained_on = `${items.length} 件 ${new Date().toLocaleDateString()} ep${ep}`; $("#i-save").disabled = false;
  const cell = (m, k) => m[k] ? `${(m[k].acc * 100).toFixed(1)}% / Brier ${m[k].brier.toFixed(3)} (n=${m[k].n})` : "—";
  $("#i-out").innerHTML = `<table><tr><th></th><th>学習前</th><th>学習後</th></tr><tr><td>train</td><td>${cell(before, "tr")}</td><td>${cell(after, "tr")}</td></tr><tr><td><b>val（未使用）</b></td><td>${cell(before, "val")}</td><td><b>${cell(after, "val")}</b></td></tr></table><p class="muted small">${((performance.now() - t0) / 1000).toFixed(1)} 秒。val が上がっていれば「保存して使う」。下がったら過学習（エポック↓・件数↑）。</p>`;
  const c = $("#i-curve"); c.classList.remove("hidden"); const g = c.getContext("2d"); g.clearRect(0, 0, c.width, c.height); const mx = Math.max(...curve.map(x => x.loss)) || 1; g.strokeStyle = "#b45309"; g.lineWidth = 2; g.beginPath(); curve.forEach((x, k) => { const X = 30 + k / Math.max(1, curve.length - 1) * (c.width - 60), Y = c.height - 20 - x.loss / mx * (c.height - 40); k ? g.lineTo(X, Y) : g.moveTo(X, Y); }); g.stroke(); g.strokeStyle = "#0b6e99"; g.beginPath(); curve.forEach((x, k) => { const X = 30 + k / Math.max(1, curve.length - 1) * (c.width - 60), Y = c.height - 20 - x.acc * (c.height - 40); k ? g.lineTo(X, Y) : g.moveTo(X, Y); }); g.stroke(); g.fillStyle = "#6b7280"; g.font = "12px system-ui"; g.fillText("損失（橙）・train 精度（青）×エポック", 30, 14);
  await saveNote({ kind: "improve", name: `head 学習 ${items.length} 件`, model: jev.name, n_states: items.length, epochs: ep, lr, lam, before, after }); status(""); };
$("#i-save").onclick = async () => { if (!trainedHead) return; await jev.saveCustomHead(trainedHead, trainedHead.trained_on); refreshImprove(); alert("保存しました。以後この端末の " + jev.name + " はこのヘッドを使います（Playground のヘッダに head:custom と出ます）"); $("#mstate").textContent = $("#mstate").textContent.replace("ヘッド:書き出し", "ヘッド:端末学習"); };
$("#i-reset").onclick = async () => { if (!jev || jev.kind !== "jev_ja") return; await jev.resetCustomHead(); trainedHead = null; refreshImprove(); alert("書き出し時のヘッドに戻しました"); };
$("#i-export").onclick = () => { const h = trainedHead || jev?.headCustom || jev?.headExport; if (h) download(`head-${jev.name}-${Date.now()}.json`, JSON.stringify(h.toJSON())); };
$("#i-import").onchange = async e => { const f = e.target.files[0]; if (!f || !jev || jev.kind !== "jev_ja") return; const h = HeadJS.fromJSON(JSON.parse(await f.text())); await jev.saveCustomHead(h, "import " + f.name); refreshImprove(); alert("読み込んで保存しました"); };

/* ================= OSINT（メイン） ================= */
$("#o-src").innerHTML = Object.entries(SOURCES).map(([k, s]) => `<label style="display:block"><input type="checkbox" class="o-s" value="${k}" ${["jma", "wikipedia", "nominatim", "bluesky"].includes(k) ? "checked" : ""} style="width:auto"> <b>${s.name}</b> <span class="muted small">${s.desc}</span></label>`).join("");
OSINT_PRESETS.forEach(p => { const o = document.createElement("option"); o.value = p.id; o.textContent = p.name; $("#o-preset").appendChild(o); });
