let oItems = [], oJudged = null, oGeo = [], oClusters = null, oLabels = {};
const W = { ...TRUST_WEIGHTS_DEFAULT }; const WN = { official: "公的発表", supported: "根拠と整合", has_specifics: "具体性", kind_report: "種類", no_spread: "拡散依頼なし", relevant: "関連" };
$("#o-w").innerHTML = Object.keys(W).map(k => `<span>${WN[k]}</span><span><input type="range" class="o-wk" data-k="${k}" min="0" max="1" step="0.05" value="${W[k]}" style="width:60%"> <b class="o-wv" data-k="${k}">${W[k].toFixed(2)}</b></span>`).join("");
$$(".o-wk").forEach(r => r.oninput = () => { W[r.dataset.k] = +r.value; $(`.o-wv[data-k=${r.dataset.k}]`).textContent = (+r.value).toFixed(2); if (oJudged) renderOsint(); });
function savedQueries() { try { const q = JSON.parse(localStorage.getItem("jev.queries") || "[]"); $("#o-saved").innerHTML = q.map(x => `<option value="${esc(x)}">`).join(""); $("#o-hist").innerHTML = '<option value="">— 過去の検索 —</option>' + q.map(x => `<option>${esc(x)}</option>`).join(""); return q; } catch { return []; } } savedQueries();
const oCtx = () => $("#o-ctx").value.split("\n").map(s => s.trim()).filter(Boolean);
async function doCollect(q) { const srcs = $$(".o-s:checked").map(c => c.value); oJudged = null; oClusters = null; oLabels = {}; $("#o-diff").textContent = ""; try { const qs = savedQueries(); localStorage.setItem("jev.queries", JSON.stringify([q, ...qs.filter(x => x !== q)].slice(0, 20))); } catch { }
  const queries = q.split(/[,、，]/).map(s => s.trim()).filter(Boolean); oItems = [];
  for (const qq of queries) { status(`「${qq}」を収集中…`); const got = await collect(qq, srcs.filter(s => queries.indexOf(qq) === 0 || s !== "jma"), { limit: +$("#o-limit").value || 5, prefCode: $("#o-pref").value, lang: $("#o-lang").value }, status); got.forEach(it => it.query = qq); oItems.push(...got); }
  const seenUrl = new Set(); oItems = oItems.filter(it => { if (it.error || !it.url) return true; if (seenUrl.has(it.url)) return false; seenUrl.add(it.url); return true; });
  try { const key = "osint:seen:" + q; const seen = new Set(await store.get(key) || []); const now = oItems.filter(i => !i.error).map(i => i.url); const fresh = now.filter(u => !seen.has(u)); oItems.forEach(i => { if (!i.error) i.is_new = !seen.has(i.url); }); await store.put(key, [...new Set([...seen, ...now])]); $("#o-diff").textContent = seen.size ? `前回から新着 ${fresh.length} 件（🆕）` : "初回の収集（次回から新着を検出）"; } catch { }
  oGeo = []; if ($("#o-geo").checked) { status("地理照合中…"); oGeo = await geoContext(oItems); }
  const official = oItems.filter(i => !i.error && (i.official || i.source === "wikipedia")).map(i => `${i.title}: ${(i.text || "").slice(0, 200)}`).slice(0, 4); $("#o-ctx").value = [...official, ...oGeo.slice(0, 3)].join("\n");
  if ($("#o-cluster").checked && jev?.kind === "jev_ja") { status("類似投稿をまとめ中…"); const idx = oItems.map((it, i) => i).filter(i => !oItems[i].error); const vecs = []; for (const i of idx) vecs.push(await jev.embed(`${oItems[i].title} ${oItems[i].text}`)); const cl = clusterByCos(vecs, +$("#o-th").value || 0.9); oClusters = {}; idx.forEach((i, n) => oClusters[i] = cl[n]); }
  $("#o-judge").disabled = !jev; ["#o-pack", "#o-csv", "#o-md", "#o-label"].forEach(s => $(s).disabled = false); status(""); renderOsint(); savedQueries();
  if ($("#o-auto").checked && jev && oItems.some(i => !i.error)) await doJudge(); }
$("#o-run").onclick = async () => { const q = $("#o-q").value.trim(); if (!q) { $("#o-q").focus(); return status("キーワードを入れてください"); } $("#o-run").disabled = true; try { await doCollect(q); } catch (e) { status("収集エラー: " + e.message); } $("#o-run").disabled = false; };
async function doJudge() { const q = $("#o-q").value; const qs = OSINT_QUESTIONS(q); const ctxs = oCtx(); oJudged = []; for (let i = 0; i < oItems.length; i++) { const it = oItems[i]; if (it.error) { oJudged.push(null); continue; } status(`整理中 ${i + 1}/${oItems.length}`); const c = ctxs.filter(x => !x.startsWith((it.title || "") + ":")); const r = await jev.decide(`${it.title}\n${it.text}`, qs, c.length ? c : null, curOpts()); const j = {}; for (const a of r.answers) j[a.id] = a; j._ms = r.latency_ms; oJudged.push(j); } status(""); $("#o-note").disabled = false; renderOsint(); }
$("#o-judge").onclick = async () => { if (ready()) await doJudge(); };
function renderOsint() { const nOk = oItems.filter(i => !i.error).length; const nCl = oClusters ? new Set(Object.values(oClusters)).size : null; const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null;
  $("#o-stats").innerHTML = `<span class="stat">取得<br><b>${nOk}</b></span>${nCl != null ? `<span class="stat">類似群<br><b>${nCl}</b></span>` : ""}${oGeo.length ? `<span class="stat">地理根拠<br><b>${oGeo.length}</b></span>` : ""}${ts ? `<span class="stat">公的発表<br><b>${oJudged.filter(j => j?.kind?.choice === "公的機関の発表").length}</b></span><span class="stat">拡散依頼<br><b>${oJudged.filter(j => j?.asks_spread?.noul).length}</b></span><span class="stat">高信頼(≥70)<br><b>${ts.filter(t => t && t.score >= 0.7).length}</b></span>` : ""}`;
  let h = `<table><tr><th>#</th><th>出典</th><th>内容</th><th>時刻</th>` + (oClusters ? "<th>群</th>" : "") + (oJudged ? "<th>信頼性</th><th>関連</th><th>種類</th><th>緊急</th><th>具体</th><th>拡散</th><th>整合</th>" : "") + "<th>人手ラベル</th></tr>";
  const flt = $("#o-filter").value.trim().split(/[,、\s]+/).filter(Boolean); const hl = t => { let s = esc(t); for (const f of flt) s = s.replace(new RegExp(f.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), m => `<mark>${m}</mark>`); return s; };
  const order = [...oItems.keys()].sort((x, y) => ts ? ((ts[y]?.score ?? -1) - (ts[x]?.score ?? -1)) : 0).filter(i => { const it = oItems[i]; if (it.error) return true; if ($("#o-only-new").checked && !it.is_new) return false; if ($("#o-only-official").checked && !(it.official || oJudged?.[i]?.kind?.choice === "公的機関の発表" || oJudged?.[i]?.kind?.choice === "報道")) return false; if (flt.length) { const t = `${it.title} ${it.text} ${it.source}`.toLowerCase(); if (!flt.some(f => t.includes(f.toLowerCase()))) return false; } return true; });
  h = h.replace("<table>", `<p class="muted small">表示 ${order.filter(i => !oItems[i].error).length} 件</p><table>`);
  for (const i of order) { const it = oItems[i]; if (it.error) { h += `<tr><td>${i}</td><td>${it.source}</td><td class="muted" colspan=12>取得失敗: ${esc(it.error).slice(0, 120)}</td></tr>`; continue; }
    h += `<tr><td>${i}</td><td>${it.official ? "🏛 " : ""}${it.source}${it.is_new ? " 🆕" : ""}${it.query && it.query !== $("#o-q").value ? `<br><span class="pill">${esc(it.query)}</span>` : ""}<br><a href="${esc(it.url)}" target="_blank" rel="noopener" class="small">開く</a> <button class="small o-addctx" data-i="${i}" title="この情報を根拠（context）に追加">＋根拠</button></td><td><details><summary><b>${hl(it.title || "")}</b> <span class="muted small">${hl((it.text || "").slice(0, 100))}</span></summary><p class="small">${hl(it.text || "")}</p>${it.elevation_m != null ? `<span class="pill">標高 ${it.elevation_m.toFixed(0)}m</span>` : ""}${oJudged?.[i] ? `<p class="small muted">${Object.entries(oJudged[i]).filter(([k]) => k !== "_ms").map(([k, a]) => `${k}: ${esc(lab(a))} (${(a.confidence * 100).toFixed(0)}%)`).join(" / ")}</p>` : ""}</details></td><td class="small">${(it.time || "").slice(0, 16)}</td>`;
    if (oClusters) h += `<td>${oClusters[i] ?? ""}</td>`;
    if (oJudged) { const j = oJudged[i], t = ts[i]; if (!j) h += "<td colspan=7></td>"; else { const ny = a => a ? (a.noul ? "✅" : "—") + ` <span class="muted small">${a.p_yes.toFixed(2)}</span>` : ""; h += `<td><b>${(t.score * 100).toFixed(0)}</b><div class="bar"><i style="width:${t.score * 100}%"></i></div><span class="muted small" title="${Object.entries(t.parts).map(([k, v]) => WN[k] + "=" + v.toFixed(2)).join(", ")}">内訳▸</span></td><td>${ny(j.relevant)}</td><td>${esc(j.kind?.choice || "")}<br><span class="muted small">${j.kind ? (j.kind.confidence * 100).toFixed(0) + "%" : ""}</span></td><td>${j.urgency ? j.urgency.score.toFixed(1) : ""}</td><td>${ny(j.has_specifics)}</td><td>${ny(j.asks_spread)}</td><td>${ny(j.supported)}</td>`; } }
    h += `<td><select class="o-lab" data-i="${i}" style="width:auto"><option value="">種類</option>${["公的機関の発表", "報道", "一般の投稿・目撃", "意見・感想", "宣伝・無関係"].map(k => `<option ${oLabels[i]?.kind === k ? "selected" : ""}>${k}</option>`).join("")}</select> <select class="o-lab-t" data-i="${i}" style="width:auto"><option value="">信頼</option>${["高", "中", "低"].map(k => `<option ${oLabels[i]?.trust === k ? "selected" : ""}>${k}</option>`).join("")}</select></td></tr>`; }
  $("#o-out").innerHTML = h + "</table>"; $$(".o-addctx").forEach(b => b.onclick = () => { const it = oItems[b.dataset.i]; const line = `${it.title}: ${(it.text || "").slice(0, 200)}`; $("#o-ctx").value = [...oCtx().filter(x => x !== line), line].join("\n"); status("根拠に追加しました"); }); $$(".o-lab").forEach(sel => sel.onchange = () => { (oLabels[sel.dataset.i] ??= {}).kind = sel.value; }); $$(".o-lab-t").forEach(sel => sel.onchange = () => { (oLabels[sel.dataset.i] ??= {}).trust = sel.value; }); }
const judgedPlain = () => oJudged?.map(j => j && Object.fromEntries(Object.entries(j).filter(([k]) => k !== "_ms").map(([k, a]) => [k, { label: lab(a), score: a.score, p_yes: a.p_yes, confidence: a.confidence }])));
$("#o-pack").onclick = () => download(`evidence-${Date.now()}.json`, JSON.stringify({ ...evidencePack($("#o-q").value, oItems, judgedPlain()), geo_context: oGeo, context_used: oCtx(), clusters: oClusters, trust_weights: W, human_labels: oLabels }, null, 1));
$("#o-csv").onclick = () => { const cell = v => `"${String(v ?? "").replace(/"/g, '""')}"`; const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; download("osint.csv", "﻿" + ["i,source,title,text,time,url,fetched_at,is_new,cluster,elevation_m,trust,relevant,kind,urgency,has_specifics,asks_spread,supported,label_kind,label_trust"].concat(oItems.map((it, i) => { const j = oJudged?.[i]; return [i, it.source, it.title, it.text, it.time, it.url, it.fetched_at, it.is_new ? 1 : 0, oClusters?.[i], it.elevation_m, ts?.[i]?.score?.toFixed(3), j?.relevant?.p_yes?.toFixed(2), j?.kind?.choice, j?.urgency?.score?.toFixed(2), j?.has_specifics?.p_yes?.toFixed(2), j?.asks_spread?.p_yes?.toFixed(2), j?.supported?.p_yes?.toFixed(2), oLabels[i]?.kind, oLabels[i]?.trust].map(cell).join(","); })).join("\n"), "text/csv"); };
$("#o-md").onclick = () => { const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; download(`report-${Date.now()}.md`, markdownReport($("#o-q").value, oItems, oJudged, ts, oClusters, oGeo), "text/markdown"); };
$("#o-note").onclick = async () => { const o = curOpts(); await saveNote({ kind: "osint", name: `OSINT: ${$("#o-q").value}`, model: jev.name, method: o.method, pool: o.pool, T: o.T, cosScale: o.cosScale, query: $("#o-q").value, n_items: oItems.length, trust_weights: { ...W }, items: evidencePack($("#o-q").value, oItems, null).items, judged: judgedPlain(), human_labels: oLabels }); alert("保存しました"); };
$("#o-label").onclick = () => { const q = $("#o-q").value; const lines = []; oItems.forEach((it, i) => { const L = oLabels[i]; if (it.error || !L || (!L.kind && !L.trust)) return; const qs = [], gold = {}; if (L.kind) { qs.push(OSINT_QUESTIONS(q)[1]); gold.kind = L.kind; } if (L.trust) { qs.push({ type: "score", id: "trust", instructions: "この情報の信頼性", levels: ["低", "中", "高"] }); gold.trust = L.trust; } lines.push(JSON.stringify({ id: `osint-${Date.now()}-${i}`, family: "osint_ja", split: "in_domain", state: `${it.title}\n${it.text}`, context: oGeo.slice(0, 3), meta: { query: q, source: it.source, url: it.url, time: it.time }, questions: qs, gold })); }); if (!lines.length) return alert("ラベルを付けた行がありません"); download(`osint_ja-${Date.now()}.jsonl`, lines.join("\n") + "\n", "application/jsonl"); };

/* ================= チャット ================= */
function botSay(html) { const d = document.createElement("div"); d.className = "msg bot"; d.innerHTML = html; $("#chat").appendChild(d); $("#chat").scrollTop = 1e9; }
function meSay(t) { const d = document.createElement("div"); d.className = "msg me"; d.textContent = t; $("#chat").appendChild(d); $("#chat").scrollTop = 1e9; }
let chatCtx = [];
const chatQs = () => { const qs = readQuestions(); return qs.length ? qs : OSINT_QUESTIONS($("#o-q").value || "話題"); };
function explain(a) { if (a.type === "choice") return `<b>${esc(a.id)}</b>: ${esc(a.choice)}（${(a.confidence * 100).toFixed(0)}%）`; if (a.type === "score") return `<b>${esc(a.id)}</b>: ${a.score.toFixed(2)}（最頻 ${esc(a.level)}）`; return `<b>${esc(a.id)}</b>: ${a.noul ? "はい" : "いいえ"}（p=${a.p_yes.toFixed(2)}）`; }
async function chatHandle(text) {
  if (text === "/help") return botSay("コマンド: <code>/q choice id 質問 | 選択肢…</code>, <code>/q score id 質問 | 段階…</code>, <code>/q noul id 質問</code>, <code>/ctx 根拠</code>, <code>/ctx clear</code>, <code>/osint 調べたいこと</code>, <code>/preset jev|ai_jp|disaster…</code>, <code>/qs</code>（今の質問）, <code>/clear</code>");
  if (text === "/clear") { $("#chat").innerHTML = ""; return; }
  if (text === "/qs") return botSay("いまの質問：<br>" + chatQs().map(q => `・${esc(q.id)} [${q.type}] ${esc(q.instructions)}${q.options ? " {" + q.options.map(esc).join(" | ") + "}" : q.levels ? " {" + q.levels.map(esc).join(" < ") + "}" : ""}`).join("<br>"));
  if (text.startsWith("/ctx")) { const c = text.slice(4).trim(); if (c === "clear") { chatCtx = []; return botSay("根拠を消しました"); } chatCtx.push(c); return botSay(`根拠を追加（${chatCtx.length} 件）`); }
  if (text.startsWith("/preset")) { const id = text.slice(7).trim(); const p = OSINT_PRESETS.find(x => x.id === id) || OSINT_PRESETS.find(x => x.name.includes(id)); if (!p) return botSay("プリセット: " + OSINT_PRESETS.map(x => `<code>${x.id}</code>`).join(" ")); $("#o-preset").value = p.id; $("#o-preset").onchange(); return botSay(`プリセット「${esc(p.name)}」を設定。<code>/osint</code> で収集します`); }
  if (text.startsWith("/q ")) { const m = /^\/q\s+(choice|score|noul)\s+(\S+)\s+(.*)$/s.exec(text); if (!m) return botSay("書式: /q choice id 質問 | 選択肢1 | 選択肢2"); const [_, type, id, rest] = m; const parts = rest.split("|").map(s => s.trim()).filter(Boolean); const q = { type, id, instructions: parts[0] }; if (type === "choice") q.options = parts.slice(1); if (type === "score") q.levels = parts.slice(1); if ((type !== "noul") && (q.options || q.levels).length < 2) return botSay("選択肢は 2 つ以上"); const qs = readQuestions().filter(x => x.id !== id); setQuestions([...qs, q]); return botSay(`質問 <b>${esc(id)}</b> を追加（計 ${qs.length + 1}）`); }
  if (text.startsWith("/osint")) { const q = text.slice(6).trim() || $("#o-q").value; $("#o-q").value = q; botSay(`「${esc(q)}」を収集中…`); await doCollect(q); if (jev) await doJudge(); const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; const ok = oItems.filter(i => !i.error); const top = [...ok.keys()].map(k => oItems.indexOf(ok[k])).sort((x, y) => (ts?.[y]?.score ?? 0) - (ts?.[x]?.score ?? 0)).slice(0, 5);
    return botSay(`${ok.length} 件取得${oJudged ? "・整理済" : ""}。信頼性の高い順:<br>` + top.map(i => `・[${oItems[i].source}] ${esc(oItems[i].title || "")}${ts?.[i] ? ` <span class="pill">${(ts[i].score * 100).toFixed(0)}</span>` : ""}${oJudged?.[i]?.kind ? ` <span class="muted small">${esc(oJudged[i].kind.choice)}</span>` : ""}`).join("<br>") + `<br><span class="muted small">詳細は「情報収集」タブ</span>`); }
  if (!ready()) return; const qs = chatQs(); const r = await jev.decide(text, qs, chatCtx.length ? chatCtx : null, curOpts());
  let h = r.answers.map(explain).join("<br>"); h += `<br><span class="muted small">${esc(jev.name)} ・ ${r.latency_ms.toFixed(0)} ms${chatCtx.length ? " ・ 根拠 " + chatCtx.length + " 件" : ""}</span>`; for (const a of r.answers) { const d = a.distribution; h += `<details><summary class="small">${esc(a.id)} の分布</summary>` + d.labels.map((l, i) => `<div class="small">${esc(l)} <div class="bar"><i style="width:${d.probabilities[i] * 100}%"></i></div></div>`).join("") + "</details>"; } botSay(h);
}
$("#c-send").onclick = async () => { const t = $("#c-in").value.trim(); if (!t) return; meSay(t); $("#c-in").value = ""; try { await chatHandle(t); } catch (e) { botSay("エラー: " + esc(e.message)); } };
$("#c-in").onkeydown = e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); $("#c-send").click(); } };
$$(".c-quick").forEach(b => b.onclick = () => { meSay(b.dataset.q); chatHandle(b.dataset.q); });
botSay("こんにちは。JEV チャットです。モデルを読み込んでから文章を送ってください。<code>/help</code> でコマンド一覧、<code>/osint 津市 大雨</code> で収集→整理まで実行します。");

/* ================= 実験ノート ================= */
async function saveNote(e) { e.id = e.id || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`; e.time = e.time || new Date().toISOString(); e.device = e.device || navigator.userAgent; e.notes = e.notes || ""; await store.expPut(e); return e.id; }
$("#p-note").onclick = async () => { if (!last) return; const o = curOpts(); await saveNote({ kind: "decide", name: prompt("実験名", `${jev.name} ${optsLabel(o)}`) || "decide", model: jev.name, method: o.method, pool: o.pool, T: o.T, cosScale: o.cosScale, input: last.input, n_tokens: last.n_tokens, timing: last.timing, answers: last.answers.map(a => ({ id: a.id, type: a.type, label: lab(a), confidence: a.confidence, labels: a.distribution.labels, probabilities: a.distribution.probabilities })) }); alert("保存しました"); };
async function refreshNotes() { const es = (await store.expAll()).sort((x, y) => y.time.localeCompare(x.time)); for (const id of ["#n-a", "#n-b"]) $(id).innerHTML = es.filter(e => e.kind === "batch").map(e => `<option value="${e.id}">${esc(e.name)}</option>`).join(""); if (!es.length) { $("#n-list").innerHTML = '<p class="muted">まだ記録がありません。</p>'; return; }
  $("#n-list").innerHTML = "<table><tr><th>時刻</th><th>種別</th><th>名前</th><th>モデル</th><th>設定</th><th>データ / 入力</th><th>精度</th><th>Brier</th><th>ECE</th><th>p50</th><th>メモ</th><th></th></tr>" + es.map(e => `<tr><td class="small">${e.time.replace("T", " ").slice(0, 16)}</td><td>${e.kind}</td><td>${esc(e.name)}</td><td>${esc(e.model || "")}${e.head ? " <span class='tag'>" + e.head + "</span>" : ""}</td><td class="small">${e.method ? optsLabel(e) : ""}</td><td class="small">${esc(e.dataset || (e.input?.state || e.state || e.query || "").slice(0, 40))}</td><td>${e.accuracy != null ? (e.accuracy * 100).toFixed(1) + "%" : (e.after?.val ? `${(e.before.val.acc * 100).toFixed(0)}→${(e.after.val.acc * 100).toFixed(0)}%` : "")}</td><td>${e.brier != null ? e.brier.toFixed(3) : ""}</td><td>${e.ece != null ? e.ece.toFixed(3) : ""}</td><td>${e.latency_p50_ms != null ? e.latency_p50_ms.toFixed(0) : (e.timing ? e.timing.total_ms.toFixed(0) : "")}</td><td><input data-id="${e.id}" class="n-memo" value="${esc(e.notes || "")}" placeholder="メモ"></td><td><button data-id="${e.id}" class="n-dl">JSON</button> <button data-id="${e.id}" class="n-del">✕</button></td></tr>`).join("") + "</table>";
  $$(".n-del").forEach(b => b.onclick = async () => { await store.expDel(b.dataset.id); refreshNotes(); }); $$(".n-dl").forEach(b => b.onclick = async () => { const e = (await store.expAll()).find(x => x.id === b.dataset.id); download(`exp-${e.id}.json`, JSON.stringify(e, null, 1)); }); $$(".n-memo").forEach(i => i.onchange = async () => { const e = (await store.expAll()).find(x => x.id === i.dataset.id); e.notes = i.value; await store.expPut(e); }); }
$("#n-cmp").onclick = async () => { const es = await store.expAll(); const a = es.find(e => e.id === $("#n-a").value), b = es.find(e => e.id === $("#n-b").value); if (!a || !b) return; const fams = [...new Set([...Object.keys(a.per_family || {}), ...Object.keys(b.per_family || {})])]; $("#n-cmp-out").innerHTML = `<table><tr><th></th><th>${esc(a.name)}</th><th>${esc(b.name)}</th><th>差</th></tr><tr><td>精度</td><td>${(a.accuracy * 100).toFixed(1)}%</td><td>${(b.accuracy * 100).toFixed(1)}%</td><td>${((b.accuracy - a.accuracy) * 100).toFixed(1)}</td></tr><tr><td>Brier</td><td>${a.brier.toFixed(3)}</td><td>${b.brier.toFixed(3)}</td><td>${(b.brier - a.brier).toFixed(3)}</td></tr><tr><td>ECE</td><td>${a.ece.toFixed(3)}</td><td>${b.ece.toFixed(3)}</td><td>${(b.ece - a.ece).toFixed(3)}</td></tr>${fams.map(f => `<tr><td>${esc(f)}</td><td>${a.per_family?.[f] ? (a.per_family[f].accuracy * 100).toFixed(1) + "%" : "—"}</td><td>${b.per_family?.[f] ? (b.per_family[f].accuracy * 100).toFixed(1) + "%" : "—"}</td><td>${a.per_family?.[f] && b.per_family?.[f] ? ((b.per_family[f].accuracy - a.per_family[f].accuracy) * 100).toFixed(1) : ""}</td></tr>`).join("")}</table>`; };
$("#n-csv").onclick = async () => { const es = await store.expAll(); const cols = ["time", "kind", "name", "model", "head", "method", "pool", "T", "cosScale", "dataset", "n_states", "n_questions", "use_context", "backend", "accuracy", "brier", "ece", "latency_p50_ms", "latency_p95_ms", "notes"]; download("experiments.csv", "﻿" + [cols.join(",")].concat(es.map(e => cols.map(c => `"${String(e[c] ?? "").replace(/"/g, '""')}"`).join(","))).join("\n"), "text/csv"); };
$("#n-json").onclick = async () => download(`experiments-${Date.now()}.json`, JSON.stringify(await store.expAll(), null, 1));
$("#n-import").onchange = async e => { const f = e.target.files[0]; if (!f) return; const es = JSON.parse(await f.text()); for (const x of (Array.isArray(es) ? es : [es])) await store.expPut(x); refreshNotes(); };
$("#n-clear").onclick = async () => { if (!confirm("実験ノートを全削除しますか？")) return; for (const e of await store.expAll()) await store.expDel(e.id); refreshNotes(); };

/* ================= モデルを追加 ================= */
async function refreshModels() { const all = await listAllModels(); $("#m-list").innerHTML = "<table><tr><th>名前</th><th>種類</th><th>HF / backbone</th><th>言語</th><th>サイズ</th><th>備考</th></tr>" + all.map(m => `<tr><td>${esc(m.name)}</td><td>${m.kind}</td><td class="small">${esc(m.hf_id || m.backbone || "")}</td><td>${m.language || ""}</td><td>${m.size_mb ? m.size_mb + " MB" : ""}</td><td class="small">${esc(m.note || "")}</td></tr>`).join("") + "</table>"; }
$("#m-search-run").onclick = async () => { const q = $("#m-search").value.trim() || "jev"; $("#m-search-out").innerHTML = "検索中…"; try { const r = await (await fetch(`https://huggingface.co/api/models?search=${encodeURIComponent(q)}&sort=downloads&limit=40`)).json();
  $("#m-search-out").innerHTML = "<table><tr><th>モデル</th><th>DL</th><th>❤</th><th>タグ</th><th>ブラウザ</th><th></th></tr>" + r.map(m => { const tags = m.tags || []; const web = tags.includes("transformers.js") || tags.includes("onnx"); const lic = tags.find(t => t.startsWith("license:"))?.slice(8) || ""; const lang = tags.filter(t => ["ja", "en", "multilingual"].includes(t)).join("/"); return `<tr><td><a href="https://huggingface.co/${m.id}" target="_blank" rel="noopener">${esc(m.id)}</a></td><td>${m.downloads ?? ""}</td><td>${m.likes ?? ""}</td><td class="small">${lic} ${lang} ${tags.includes("gguf") ? "gguf" : ""} ${tags.includes("safetensors") ? "safetensors" : ""}</td><td>${web ? "✅ onnx" : "PC 用"}</td><td>${web ? `<button class="small m-fill" data-id="${m.id}">JSON に入れる</button>` : ""}</td></tr>`; }).join("") + "</table><p class='muted small'>「ブラウザ」列が ✅ でも入力形式（open-jev 形か、cross-encoder か、独自か）はモデルカードで確認が必要。open-jev 形なら kind: open-jev-onnx で動く。</p>";
  $$(".m-fill").forEach(b => b.onclick = () => { $("#m-json").value = JSON.stringify({ name: b.dataset.id.split("/").pop().replace(/[^a-z0-9]+/gi, "_").toLowerCase(), kind: "open-jev-onnx", hf_id: b.dataset.id, dtype: "q4", dtype_webgpu: "q4f16", language: "en", note: "入力形式を要確認" }, null, 1); }); } catch (e) { $("#m-search-out").textContent = "検索失敗: " + e.message; } };
$("#m-add").onclick = async () => { let e; try { e = JSON.parse($("#m-json").value); } catch (err) { return alert("JSON エラー: " + err.message); } if (!e.name || !e.kind) return alert("name, kind が必要"); if (!["open-jev-onnx", "crossenc"].includes(e.kind)) return alert("kind は open-jev-onnx か crossenc（Jev 級のみ）"); if (e.kind === "open-jev-onnx" && !e.hf_id) return alert("hf_id が必要"); const custom = (await store.get("registry:custom")) || []; await store.put("registry:custom", [...custom.filter(x => x.name !== e.name), e]); await loadIndex(); refreshModels(); alert(`${e.name} を追加しました。上のモデル欄から読み込めます`); };
$("#m-clear").onclick = async () => { await store.del("registry:custom"); await loadIndex(); refreshModels(); };

/* ================= 設定 ================= */
async function refreshSettings() { const ks = await store.keys(); const by = {}; for (const k of ks) { if (!k.includes("/")) continue; const [m] = k.split("/"); by[m] = (by[m] || 0) + ((await store.get(k))?.byteLength || 0); } $("#s-models").innerHTML = Object.keys(by).length ? "<table><tr><th>モデル</th><th>サイズ</th><th></th></tr>" + Object.entries(by).map(([m, b]) => `<tr><td>${esc(m)}</td><td>${(b / 1e6).toFixed(1)} MB</td><td><button data-m="${m}" class="s-del">削除</button></td></tr>`).join("") + "</table>" : "保存された JEV-JA はありません（HF モデルはブラウザのキャッシュに入ります）"; $$(".s-del").forEach(b => b.onclick = async () => { await removeStored(b.dataset.m); refreshSettings(); markStored(); storageInfo(); });
  $("#s-env").innerHTML = `<span>UA</span><span class="small">${navigator.userAgent}</span><span>WebGPU</span><span>${navigator.gpu ? "あり" : "なし（WASM）"}</span><span>CPU</span><span>${navigator.hardwareConcurrency ?? "?"} コア</span><span>メモリ</span><span>${navigator.deviceMemory ? navigator.deviceMemory + " GB" : "?"}</span><span>Service Worker</span><span>${navigator.serviceWorker?.controller ? "制御中" : "未"}</span><span>オンライン</span><span>${navigator.onLine ? "はい" : "いいえ"}</span>`; storageInfo(); }
$("#s-persist").onclick = async () => { const ok = await navigator.storage.persist?.(); alert(ok ? "永続化されました" : "許可されませんでした（ホーム画面に追加すると通ることがあります）"); storageInfo(); };
$("#s-clear").onclick = async () => { if (!confirm("保存した JEV-JA をすべて削除しますか？")) return; for (const k of await store.keys()) if (k.includes("/")) await store.del(k); refreshSettings(); markStored(); };
$("#s-update").onclick = async () => { const r = await navigator.serviceWorker?.getRegistration(); await r?.update(); const ks = await caches.keys(); for (const k of ks) if (k.startsWith("jev-lab-app")) await caches.delete(k); location.reload(true); };
$("#s-backup").onclick = async () => { const data = { version: VERSION, time: new Date().toISOString(), qsets: await store.get("qsets"), registry_custom: await store.get("registry:custom"), trust_weights: W, queries: JSON.parse(localStorage.getItem("jev.queries") || "[]"), experiments: await store.expAll() }; download(`jev-lab-backup-${Date.now()}.json`, JSON.stringify(data, null, 1)); };
$("#s-restore").onchange = async e => { const f = e.target.files[0]; if (!f) return; const d = JSON.parse(await f.text()); if (d.qsets) await store.put("qsets", d.qsets); if (d.registry_custom) await store.put("registry:custom", d.registry_custom); if (d.queries) localStorage.setItem("jev.queries", JSON.stringify(d.queries)); for (const x of (d.experiments || [])) await store.expPut(x); refreshQSets(); savedQueries(); await loadIndex(); alert("復元しました"); };
$("#s-dark").onchange = () => { document.documentElement.dataset.theme = $("#s-dark").checked ? "dark" : "light"; try { localStorage.setItem("jev.theme", document.documentElement.dataset.theme); } catch { } };
$("#s-big").onchange = () => { document.body.style.fontSize = $("#s-big").checked ? "17px" : ""; try { localStorage.setItem("jev.big", $("#s-big").checked ? "1" : ""); } catch { } };
try { const th = localStorage.getItem("jev.theme"); if (th) { document.documentElement.dataset.theme = th; $("#s-dark").checked = th === "dark"; } if (localStorage.getItem("jev.big")) { $("#s-big").checked = true; document.body.style.fontSize = "17px"; } } catch { }
window.addEventListener("offline", () => status("オフラインです（保存済みモデルは動きます。収集は不可）")); window.addEventListener("online", () => status(""));

/* ================= 調査ツール ================= */
DORK_PRESETS.forEach((p, i) => { const o = document.createElement("option"); o.value = i; o.textContent = p.name; $("#d-preset").appendChild(o); });
$("#d-preset").onchange = () => { const p = DORK_PRESETS[$("#d-preset").value]; if (!p) return; const map = { site: "#d-site", filetype: "#d-ft", intitle: "#d-title", inurl: "#d-url", exclude: "#d-ex", after: "#d-after", before: "#d-before" }; for (const k in map) $(map[k]).value = p.fill[k] || ""; };
$("#d-build").onclick = () => { const r = buildDorks({ q: $("#d-q").value, site: $("#d-site").value, filetype: $("#d-ft").value, intitle: $("#d-title").value, inurl: $("#d-url").value, exclude: $("#d-ex").value, after: $("#d-after").value, before: $("#d-before").value, exact: $("#d-exact").checked }); $("#d-out").innerHTML = `<p><code>${esc(r.query)}</code> <button class="small" id="d-copy">コピー</button></p><p>${r.links.map(l => `<a href="${l.url}" target="_blank" rel="noopener"><button class="small">${l.name}</button></a>`).join(" ")}</p>`; $("#d-copy").onclick = () => navigator.clipboard?.writeText(r.query); };
let lastDomain = null;
$("#t-domain-run").onclick = async () => { const d = domainOf($("#t-domain").value); if (!d) return; $("#t-domain-out").innerHTML = "調査中…"; lastDomain = await domainProfile(d, status);
  const w = lastDomain.rdap, wb = lastDomain.wayback, ct = lastDomain.crt, dn = lastDomain.dns; $("#t-domain-out").innerHTML = `<table><tr><th>項目</th><th>結果</th></tr><tr><td>DNS A</td><td class="small">${(dn.A || []).join(", ") || "なし"}</td></tr><tr><td>MX</td><td class="small">${(dn.MX || []).join(", ") || "なし"}</td></tr><tr><td>NS</td><td class="small">${(dn.NS || []).join(", ") || "なし"}</td></tr><tr><td>登録（RDAP）</td><td class="small">${w.error ? esc(w.error) + (w.whois_link ? ` <a href="${w.whois_link}" target="_blank">JPRS WHOIS</a>` : "") : `${w.registered?.slice(0, 10) || "?"} 〜 ${w.expires?.slice(0, 10) || "?"} / ${esc(w.registrar || "")} / ${(w.status || []).join(", ")}`}</td></tr><tr><td>Wayback</td><td class="small">${wb.first ? `最古 ${wb.first.timestamp.slice(0, 8)}（${wb.snapshots.length} 時点）` : "なし"} <a href="${wb.browse}" target="_blank" rel="noopener">一覧</a> ${wb.snapshots.map(s => `<a href="${s.url}" target="_blank" rel="noopener">${s.year}</a>`).join(" ")}</td></tr><tr><td>証明書ログ</td><td class="small">${ct.error ? esc(ct.error) : `${ct.count} ホスト名` + (ct.names?.length ? `<details><summary>一覧</summary>${ct.names.slice(0, 60).map(esc).join("<br>")}</details>` : "")}</td></tr></table><h2>根拠として使える要約</h2><ul>${lastDomain.context.map(c => `<li class="small">${esc(c)}</li>`).join("")}</ul>`; $("#t-domain-ctx").disabled = false; };
$("#t-domain-ctx").onclick = () => { if (!lastDomain) return; $("#o-ctx").value = [...oCtx(), ...lastDomain.context].join("\n"); status("根拠に追加しました（情報収集タブ）"); };
$("#t-domain").addEventListener("keydown", e => { if (e.key === "Enter") $("#t-domain-run").click(); });
$("#t-exif").onchange = async e => { const f = e.target.files[0]; if (!f) return; const x = await readExif(f); $("#t-exif-out").innerHTML = "<table>" + Object.entries(x).map(([k, v]) => `<tr><td>${esc(k)}</td><td class="small">${k === "map" ? `<a href="${v}" target="_blank" rel="noopener">${v}</a>` : esc(String(v))}</td></tr>`).join("") + "</table>" + (x.lat != null ? `<p><button class="small" id="t-exif-ctx">→ 根拠に追加（撮影地点の座標）</button></p>` : ""); const b = $("#t-exif-ctx"); if (b) b.onclick = () => { $("#o-ctx").value = [...oCtx(), `画像 ${x.file}: 撮影 ${x.DateTimeOriginal || x.DateTime || "?"}, 位置 ${x.lat}, ${x.lon}, 機種 ${x.Make || ""} ${x.Model || ""}`].join("\n"); status("根拠に追加しました"); }; };
$("#t-img-run").onclick = () => { const u = $("#t-img").value.trim(); if (!u) return; $("#t-img-out").innerHTML = reverseImageLinks(u).map(l => `<a href="${l.url}" target="_blank" rel="noopener"><button class="small">${l.name}</button></a>`).join(" "); };

/* ================= boot ================= */
setQuestions([]); refreshQSets(); $("#ver").textContent = VERSION;
await loadIndex(); storageInfo();
try { const lastM = localStorage.getItem("jev.lastModel"); if (lastM && models.some(m => m.name === lastM)) $("#model").value = lastM; } catch { }
try { const t = localStorage.getItem("jev.tab"); showTab(t && $("#t-" + t) ? t : "osint"); } catch { showTab("osint"); }
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js").then(() => setTimeout(offlineCheck, 800));
try { const m = models.find(x => x.name === $("#model").value); if (localStorage.getItem("jev.lastModel") && (m?.kind !== "jev_ja" || await isStored($("#model").value))) $("#load").click(); } catch { }
